package ai.decisionos.aside;
import android.content.Context;import org.json.*;import java.util.*;
/** Device-owned group rooms share the chronological conversation repository, never goal memory. */
final class GroupRooms {
 static boolean isGroup(JSONObject row){return "group".equals(row.optString("roomType"));}
 static JSONObject goals(GoalStore s){JSONObject out=new JSONObject();for(GoalRules.Preset p:GoalRules.PRESETS){JSONObject chosen=null;for(JSONObject g:s.goals())if(!GoalStore.fixture(g)&&p.id.equals(g.optString("character"))){chosen=g;break;}if(chosen==null)chosen=s.create(p.id,p.title,p.topic,0);GoalStore.put(out,p.id,chosen.optString("id"));}return out;}
 static JSONObject latest(Context c,boolean fresh){try(GoalStore s=new GoalStore(c)){if(!fresh){String selected=c.getSharedPreferences("group_rooms",0).getString("selected","");if(!selected.isEmpty())try{JSONObject r=s.workspaceRow("conversations",selected);if(isGroup(r))return r;}catch(Exception ignored){}for(JSONObject r:s.workspace("conversations",null))if(isGroup(r))return r;}JSONObject goals=goals(s),r=s.createConversation(goals.optString("grades"),"누비와 친구들");GoalStore.put(r,"roomType","group");GoalStore.put(r,"goals",goals);s.saveWorkspace("conversations",r);select(c,r.optString("id"));return r;}}
 static void select(Context c,String id){try(GoalStore s=new GoalStore(c)){if(!isGroup(s.workspaceRow("conversations",id)))throw new IllegalArgumentException();}c.getSharedPreferences("group_rooms",0).edit().putString("selected",id).apply();}
 static JSONObject room(Context c){return latest(c,false);}
 static void save(Context c,String id,JSONArray messages,JSONObject pending){try(GoalStore s=new GoalStore(c)){JSONObject row=s.workspaceRow("conversations",id);if(!isGroup(row)||messages.length()>400)throw new IllegalArgumentException();for(int n=0;n<messages.length();n++){JSONObject m=messages.optJSONObject(n);if(m==null)throw new IllegalArgumentException();if(!Arrays.asList("user","nubi","grades","love","fitness","home","career","travel").contains(m.optString("role"))||m.optString("text").length()>12000)throw new IllegalArgumentException();}s.saveConversation(id,messages,"");row=s.workspaceRow("conversations",id);GoalStore.put(row,"pending",pending==null?JSONObject.NULL:pending);s.saveWorkspace("conversations",row);}}
 static void append(Context c,JSONObject work,JSONObject result){try(GoalStore s=new GoalStore(c)){android.database.sqlite.SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{JSONObject row=s.workspaceRow("conversations",work.optString("conversation_id"));if(!isGroup(row))throw new IllegalArgumentException();JSONArray list=row.optJSONArray("messages");if(list==null)list=new JSONArray();String prefix="scheduled-"+work.optString("id")+"-";upsert(list,prefix+"user","user",work.optString("prompt"),work,null);JSONArray replies=result==null?null:result.optJSONArray("messages");for(int n=0;replies!=null&&n<replies.length();n++){JSONObject m=replies.getJSONObject(n);upsert(list,prefix+"reply-"+n,m.optString("role"),m.optString("text"),work,m);}String state=result==null?"running":result.optString("state","running");JSONArray progress=result==null?null:result.optJSONArray("progress");String status=result==null?"자동봇이 요청했어. 필요한 친구와 함께 처리할게.":state.equals("running")?(progress!=null&&progress.length()>0?progress.optString(progress.length()-1):"필요한 정보를 확인하고 있어."):result.optString("error",state.equals("completed")?"작업을 마쳤어. 이 대화에 결과를 남겼어.":"실행 결과 확인이 필요해.");JSONObject mark=new JSONObject();GoalStore.put(mark,"actual",false);GoalStore.put(mark,"state",state);for(int n=list.length()-1;n>=0;n--)if((prefix+"status").equals(list.optJSONObject(n).optString("id")))list.remove(n);if(!state.equals("completed")||replies==null||replies.length()==0)upsert(list,prefix+"status","nubi",status,work,mark);GoalStore.put(row,"messages",list);s.saveWorkspace("conversations",row);db.setTransactionSuccessful();}catch(JSONException e){throw new IllegalArgumentException(e);}finally{db.endTransaction();}}}
 static void upsert(JSONArray list,String id,String role,String text,JSONObject work,JSONObject source){JSONObject m=null;for(int n=0;n<list.length();n++)if(id.equals(list.optJSONObject(n).optString("id")))m=list.optJSONObject(n);if(m==null){m=new JSONObject();list.put(m);GoalStore.put(m,"at",System.currentTimeMillis());}GoalStore.put(m,"id",id);GoalStore.put(m,"role",role);GoalStore.put(m,"text",text);GoalStore.put(m,"scheduledWorkId",work.optString("id"));if(source!=null){for(String k:new String[]{"model","actual","state"})if(source.has(k))GoalStore.put(m,k,source.opt(k));if(source.has("model")&&!source.has("actual"))GoalStore.put(m,"actual",true);}}
}
